Here's a C++ function that takes a reference to a std::string containing markdown formatted text and converts it to HTML formatted text:
<code1>
#include <string>
#include <iostream>
#include <unordered_map>  <comments added for clarification>

// Mapping of markdown syntax to HTML equivalents
static const std::unordered_map<std::string, std::string> markdown_to_html{
    {"# ", "<h1>"},     // Heading 1
    {"## ", "<h2>"},    // Heading 2
    {"### ", "<h3>"},   // Heading 3
    {"#### ", "<h4>"},  // Heading 4
    {"##### ", "<h5>"}, // Heading 5
    {"###### ", "<h6>"},// Heading 6
    {"* ", "<li>"},     // Unordered list item
    {"1. ", "<li>"}     // Ordered list item
};

// Function to convert Markdown to HTML
std::string markdownToHTML(std::string& markdown_text) {
    std::ostringstream html_text;

    for (size_t i = 0; i < markdown_text.length(); ++i) {
        std::string markup;  // Temporary string to store markdown syntax

        // Check for start of a block-level element (e.g., headings, lists)
        if (i + 3 < markdown_text.length() && markdown_to_html.count(markdown_text.substr(i, 3)) > 0) {
            markup = markdown_text.substr(i, 3);
            html_text << markdown_to_html.at(markdown_text.substr(i, 3));
            i += 3;  // Advance index by the length of the markup
        }

        // Handle inline elements like bold/italic text and links
        else if (markdown_text[i] == '`' && markdown_text[i + 1] == '`') {
            markup = "``";
            html_text << "<code>";
            ++i;  // Advance index to process the next character
        } else if (markdown_text[i] == '*' || markdown_text[i] == '_' || markdown_text[i] == '~') {
            int start = i;
            while (markdown_text[start] == markup[0] && start < markdown_text.length()) {
                ++start;
            }
            markup = markdown_text.substr(i, start - i);  // Capture matched characters

            if (markup[0] == '*' && markup[1] == '*') {
                html_text << "<b>";
            } else if (markup[0] == '_' && markup[1] == '_') {
                html_text << "<em>";
            } else if (markup[0] == '~' && markup[1] == '~') {
                html_text << "<del>";
            }
            html_text << markup.substr(1, markup.length() - 2) << "</" << markup.substr(0, 1) << ">";
            i = start - 1;  // Adjust index to process the next character after the matched text
        } else if (markdown_text[i] == '[' && markdown_text[i + 1] != '[') {
            int start = i;
            while ((markdown_text[start] == '[' || markdown_text[start] == '(') && start < markdown_text.length()) {
                ++start;
            }
            markup = markdown_text.substr(i, start - i);  // Capture link reference

            int end = start;
            while ((markdown_text[end] == ']' || markdown_text[end] == ')') && end < markdown_text.length()) {
                ++end;
            }
            std::string link = markdown_text.substr(start, end - start);  // Extract link target

            html_text << '<a href="' << link << '">' << markup.substr(1, markup.length() - 2) << "</a>";
            i = end - 1;  // Adjust index to process the next character after the matched text
        }

        // HANDLE TEXT NOT MATCHING ANY MARKUP CONVENTION
        else {
            html_text << markdown_text[i];
        }
    }

    return html_text.str();
}
</code1>

This function uses an unordered map to map common markdown syntax patterns (e.g., heading markers, list indicators) to their corresponding HTML tags. It iterates through the input markdown_text string character by character, checking for known markdown syntax patterns and converting them to HTML. For inline elements such as bold/italic text and links, the function captures the matched characters and inserts the appropriate HTML tags. Text not matching any markdown patterns is directly added to the output HTML string. The function returns the HTML-formatted string in the std::string object `html_text`.

